<script setup lang="ts">
import AppIcon from '@/Components/AppIcon.vue';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';

const props = defineProps<{ loans: { data: any[]; links: any[]; total: number }; filters: { search: string; status: string }; stats: { active: number; overdue: number; closed: number; booksOut: number }; ownOnly: boolean }>();
const filters = reactive({ ...props.filters });
const applyFilters = () => router.get(route('loans.index'), filters, { preserveState: true, replace: true });
const setStatus = (status: string) => { filters.status = status; applyFilters(); };
const loanStatus = (loan: any) => loan.closed_at ? 'closed' : new Date(loan.due_at) < new Date() ? 'overdue' : 'active';
const statusLabel: Record<string, string> = { active: 'En cours', overdue: 'En retard', closed: 'Clôturé' };
const statusClass: Record<string, string> = { active: 'bg-blue-50 text-blue-700 dark:bg-blue-950 dark:text-blue-300', overdue: 'bg-red-50 text-red-700 dark:bg-red-950 dark:text-red-300', closed: 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300' };
</script>

<template><Head :title="ownOnly ? 'Mes prêts' : 'Prêts et retours'"/><AuthenticatedLayout>
    <template #header><div><p class="dw-page-kicker">Circulation des ouvrages</p><h1 class="dw-page-title">{{ ownOnly ? 'Mes prêts' : 'Prêts et retours' }}</h1><p class="dw-page-description">Suivez les livres emportés, les échéances et les retours enregistrés.</p></div></template>

    <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><button v-for="metric in [{ label:'Prêts en cours',value:stats.active,status:'active',icon:'loans',tone:'bg-blue-50 text-blue-600 dark:bg-blue-950'},{label:'En retard',value:stats.overdue,status:'overdue',icon:'loans',tone:'bg-red-50 text-red-600 dark:bg-red-950'},{label:'Livres à rendre',value:stats.booksOut,status:'active',icon:'books',tone:'bg-amber-50 text-amber-600 dark:bg-amber-950'},{label:'Prêts clôturés',value:stats.closed,status:'closed',icon:'reports',tone:'bg-emerald-50 text-emerald-600 dark:bg-emerald-950'}]" :key="metric.label" class="dw-card flex items-center gap-4 p-5 text-start hover:border-primary-300" @click="setStatus(metric.status)"><span class="flex h-11 w-11 items-center justify-center rounded-lg" :class="metric.tone"><AppIcon :name="metric.icon" class="h-5 w-5"/></span><span><strong class="block text-2xl text-slate-700 dark:text-white">{{metric.value}}</strong><span class="mt-1 block text-xs text-slate-500">{{metric.label}}</span></span></button></div>

    <section class="dw-card mt-6 p-4 sm:p-5"><form class="flex flex-col gap-3 sm:flex-row" @submit.prevent="applyFilters"><div class="relative flex-1"><AppIcon name="search" class="absolute start-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input v-model="filters.search" class="dw-field ps-11" placeholder="Étudiant, prêt ou numéro d’exemplaire…"/></div><select v-model="filters.status" class="dw-field sm:w-48"><option value="">Tous les statuts</option><option value="active">En cours</option><option value="overdue">En retard</option><option value="closed">Clôturés</option></select><button class="dw-btn-primary justify-center">Filtrer</button><button type="button" class="dw-btn-secondary" @click="filters.search='';filters.status='';applyFilters()">×</button></form></section>

    <section class="mt-6 space-y-3"><details v-for="loan in loans.data" :key="loan.id" class="dw-card group overflow-hidden" :open="!loan.closed_at"><summary class="flex cursor-pointer list-none flex-wrap items-center gap-4 p-4 marker:hidden sm:p-5"><img v-if="loan.student.photo_url" :src="loan.student.photo_url" class="h-12 w-10 rounded object-cover" alt=""/><span v-else class="flex h-10 w-10 items-center justify-center rounded-full bg-primary-50 text-xs font-bold text-primary-700">{{loan.student.first_name[0]}}{{loan.student.last_name[0]}}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm text-slate-700 dark:text-slate-200">{{loan.student.last_name}} {{loan.student.first_name}}</strong><span class="mt-1 block font-mono text-xs text-primary-600">{{loan.student.registration_number}} · {{loan.loan_number}}</span></span><span class="text-end"><strong class="block text-sm" :class="loanStatus(loan)==='overdue'?'text-red-600':'text-slate-700 dark:text-slate-200'">Retour le {{new Date(loan.due_at).toLocaleDateString('fr-FR')}}</strong><span class="mt-1 block text-xs text-slate-400">{{loan.active_items_count}} à rendre / {{loan.items_count}} livre(s)</span></span><span class="rounded-full px-2.5 py-1 text-xs font-bold" :class="statusClass[loanStatus(loan)]">{{statusLabel[loanStatus(loan)]}}</span><Link v-if="!ownOnly&&!loan.closed_at" :href="route('desk.index',{q:loan.student.registration_number})" class="rounded-md bg-primary-600 px-3 py-2 text-xs font-bold text-white" @click.stop>Enregistrer un retour</Link><AppIcon name="chevron-down" class="h-5 w-5 text-slate-400 transition group-open:rotate-180"/></summary><div class="border-t border-gray-200 dark:border-gray-900"><div v-for="item in loan.items" :key="item.id" class="flex items-center gap-4 border-b border-gray-200 p-4 last:border-0 dark:border-gray-900 sm:px-5"><img v-if="item.copy.book.cover_url" :src="item.copy.book.cover_url" class="h-14 w-10 rounded object-cover" alt=""/><span v-else class="flex h-14 w-10 items-center justify-center rounded border border-dashed border-gray-300 text-amber-500 dark:border-gray-800"><AppIcon name="books" class="h-5 w-5"/></span><span class="min-w-0 flex-1"><Link :href="route('books.show',item.copy.book.id)" class="truncate text-sm font-bold text-slate-700 hover:text-primary-600 dark:text-slate-200">{{item.copy.book.title}}</Link><span class="mt-1 block font-mono text-xs text-slate-400">{{item.copy.inventory_number}}</span></span><span class="text-xs text-slate-400">Prêté le {{new Date(item.loaned_at).toLocaleDateString('fr-FR')}}</span><span class="rounded-full px-2 py-1 text-xs font-bold" :class="item.returned_at?'bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300':'bg-amber-50 text-amber-700 dark:bg-amber-950 dark:text-amber-300'">{{item.returned_at?'Rendu':'À rendre'}}</span></div></div></details><div v-if="!loans.data.length" class="dw-card p-12 text-center"><AppIcon name="loans" class="mx-auto h-10 w-10 text-slate-300"/><p class="mt-3 text-sm text-slate-400">Aucun prêt ne correspond aux filtres.</p></div></section>
    <div v-if="loans.links?.length>3" class="mt-5 flex flex-wrap justify-center gap-1"><Link v-for="link in loans.links" :key="link.label" :href="link.url||'#'" class="rounded-md border px-3 py-2 text-xs" :class="link.active?'border-primary-600 bg-primary-600 text-white':link.url?'border-gray-300 bg-white text-slate-600 dark:border-gray-800 dark:bg-gray-950':'pointer-events-none border-gray-200 text-slate-300'" v-html="link.label"/></div>
</AuthenticatedLayout></template>
